import{_ as e,o as n,c as s,ag as p}from"./chunks/framework.PVHj0As1.js";const i="/pub-blog/assets/image-20250302225151369.D9urfCBr.png",t="/pub-blog/assets/image-20250302225223893.Cj_JRklI.png",r="/pub-blog/assets/image-20250302225238673.c33BUz2g.png",l="/pub-blog/assets/image-20250302225336850.CZmk2y7v.png",o="/pub-blog/assets/image-20250302225510808.J2YZbuT7.png",g="/pub-blog/assets/image-20250302225517705.Doaq1B5V.png",m="/pub-blog/assets/image-20250302225606141.hvIarv9z.png",c="/pub-blog/assets/image-20250302225630516.BAfek-R0.png",h="/pub-blog/assets/image-20250302225658149.ClTR1S3W.png",d="/pub-blog/assets/image-20250302225714902.DgiFOWe5.png",b="/pub-blog/assets/image-20250302225929330.C7bF7XuA.png",u="/pub-blog/assets/image-20250302230015367.Co7eIUuQ.png",_="/pub-blog/assets/image-20250302230114780.CeIXhAKp.png",k="/pub-blog/assets/image-20250302230223110.BniMvaX8.png",q="/pub-blog/assets/image-20250302230234794.vgy7Booj.png",f="/pub-blog/assets/image-20250302230244801.Cje0jDIL.png",x="/pub-blog/assets/image-20250302230349615.BE0RpQhy.png",v="/pub-blog/assets/image-20250302230409292.C1VNu3K9.png",P="/pub-blog/assets/image-20250302230435619.dQGk1vCP.png",y=JSON.parse('{"title":"腾讯云deepseek-工作流带你实现专属 风水大师","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/腾讯云deepseek-工作流带你实现专属 风水大师/腾讯云deepseek-工作流带你实现专属 风水大师.md","filePath":"AI人工智能/腾讯云deepseek-工作流带你实现专属 风水大师/腾讯云deepseek-工作流带你实现专属 风水大师.md","lastUpdated":1741103168000,"__rawMarkdown":"# 腾讯云deepseek-工作流带你实现专属 风水大师\\n\\n## 介绍\\n\\n想快速搭建一个超厉害的大模型知识问答应用吗？选择腾讯云大模型知识引擎平台就对啦！在这里，您能够轻松创建基于 DeepSeek 满血版（671B 全尺寸模型） 与 RAG（检索增强生成）技术的知识问答应用。\\n\\n只需在知识管理板块上传文档，模型便能依据企业私域知识文档，为您提供精准的知识问答服务。而且哦，腾讯云大模型知识引擎平台内置了最佳实践流程，操作超简单，您仅需进行简单配置，就能搭建出基于 DeepSeek - R1/V3 大模型的知识问答应用。不仅如此，平台还支持在对话测试窗口，让您完整体验从用户问题理解，到知识检索，再到知识问答的全流程，赶快来试试吧！\\n\\n## 登录和开通大模型知识引擎\\n\\n首先用户需要登录和[开通大模型知识引擎](https://cloud.tencent.com/product/lke)\\n\\n![image-20250302225151369](assets/image-20250302225151369.png)\\n\\n## 创建应用\\n\\n![image-20250302225223893](assets/image-20250302225223893.png)\\n\\n## 填写应用名称\\n\\n![image-20250302225238673](assets/image-20250302225238673.png)\\n\\n## 模型配置\\n\\n这里可以选择 DeepSeep-R1。火力拉满。\\n\\n![image-20250302225336850](assets/image-20250302225336850.png)\\n\\n## 角色指令\\n\\n首先可以根据自己的理解填写角色指令，如\\n\\n```\\n#角色名称：中国风水大师，精通风水、命脉、历史、人文、天文、地理\\n#风格特点：语言风格简练、文绉绉，可以多带成语、谚语\\n#输出要求：无\\n#能力限制：无\\n能够达成以下用户意图\\n##意图名称：给出用户关于今年、今月、今日的运程信息\\n##意图描述：解决用于关于对自己事业、婚姻、命运、学习等的疑问\\n##意图示例：用户最近比较倒霉，你需要给出解决用户倒霉的建议\\n##意图实现：可以追问用户更加详细的描述\\n```\\n\\n接着使用 **AI一键优化**\\n\\n![image-20250302225510808](assets/image-20250302225510808.png)\\n\\n可以看到，优化后的结果变得十分专业了。\\n\\n![image-20250302225517705](assets/image-20250302225517705.png)\\n\\n## 欢迎语\\n\\n这里填写针对用户的欢迎语\\n\\n![image-20250302225606141](assets/image-20250302225606141.png)\\n\\n它最后会在这里出现\\n\\n![image-20250302225630516](assets/image-20250302225630516.png)\\n\\n## 知识库\\n\\n如果你的输出内容需要参考已有知识库，那么可以在这里进行关联\\n\\n![image-20250302225658149](assets/image-20250302225658149.png)\\n\\n## 联网搜索\\n\\n是否联网搜索\\n\\n![image-20250302225714902](assets/image-20250302225714902.png)\\n\\n## 工作流\\n\\n如果你的功能需要分成N个步骤，才能完成，比如\\n\\n1. 获取用户的输入信息 如   98年3月20日，广州\\n2. 那么我们需要提取或者加工变成我们需要的格式   1998-03-20, 广东省-广州市\\n3. 然后将 **1998-03-20**, **广东省-广州市**  当成参数 去调用第三方接口\\n\\n以上是关于工作流的简单介绍，但是当前我们的功能不需要。\\n\\n\\n\\n## 输出方式\\n\\n这里选择流式，可以实时看到输出的内容\\n\\n![image-20250302225929330](assets/image-20250302225929330.png)\\n\\n## 调试\\n\\n填写完毕后，在可以右侧的界面中进行调试\\n\\n![image-20250302230015367](assets/image-20250302230015367.png)\\n\\n---\\n\\n输入测试内容，得到返回结果\\n\\n![image-20250302230114780](assets/image-20250302230114780.png)\\n\\n---\\n\\n可以看到，风水婆给出的建议还是很高端和专业的\\n\\n![image-20250302230223110](assets/image-20250302230223110.png)\\n\\n## 最后发布\\n\\n![image-20250302230234794](assets/image-20250302230234794.png)\\n\\n![image-20250302230244801](assets/image-20250302230244801.png)\\n\\n## 分享\\n\\n最后回到应用管理页面，**调用-分享**  即可给其他人使用了。\\n\\n![image-20250302230349615](assets/image-20250302230349615.png)\\n\\n![image-20250302230409292](assets/image-20250302230409292.png)\\n\\n### 分享链接\\n\\n```\\nhttps://lke.cloud.tencent.com/webim_exp/#/chat/LJMTGr\\n```\\n\\n### 分享二维码\\n\\n![image-20250302230435619](assets/image-20250302230435619.png)"}'),C={name:"AI人工智能/腾讯云deepseek-工作流带你实现专属 风水大师/腾讯云deepseek-工作流带你实现专属 风水大师.md"};function A(D,a,I,S,B,R){return n(),s("div",null,[...a[0]||(a[0]=[p("",59)])])}const V=e(C,[["render",A]]);export{y as __pageData,V as default};
